int phi(int n){
    int res = n;
    for(int i = 2; i <= sqrt(n); i++){
        if(n % i == 0){
            res = res - res / i;   // res *= (1 - 1/i)
            while(n % i == 0) n /= i;
        }
    }
    if(n > 1) res -= res / n;   // thừa số nguyên tố lớn còn lại
    return res;
}

int phi[1000001];
void sang(){
    for(int i = 1; i <= 1000000; i++) phi[i] = i;
    for(int i = 2; i <= 1000000; i++){
        if(phi[i] == i){          // i là số nguyên tố
            for(int j = i; j <= 1000000; j += i)
                phi[j] -= phi[j] / i;
        }
    }
}

int phi[1000001];
void sang(){
    for(int i = 1; i <= 1000000; i++) phi[i] = i - 1;
    phi[0] = 0; phi[1] = 1;
    for(int i = 2; i <= 1000000; i++)
        for(int j = 2 * i; j <= 1000000; j += i)
            phi[j] -= phi[i];
}
